def count_solutions():
    count = 0
    # b_5 must be at least 1 (since n is positive) and at most 6.
    for b5 in range(1, 7):
        # Iterate over the free variables: b1, b2, b3 (0 to 6)
        for b1 in range(7):
            for b2 in range(7):
                for b3 in range(7):
                    # Target value T = 5*b1 + 3*b2 + b3
                    T = 5 * b1 + 3 * b2 + b3

                    # Required value for b4: b4 = T - 3*b5
                    b4 = T - 3 * b5

                    # Check constraints on b4: 0 <= b4 <= 6
                    if 0 <= b4 <= 6:
                        # b0 is fixed to 0 based on the structural constraints derived previously
                        count += 1

    return count

print(count_solutions())

