def check_constraints_all(b5, b4, b3, b2, b1):
    """Checks the constraint equation: b4 + 3*b5 = 5*b1 + 3*b2 + b3"""
    LHS = b4 + 3 * b5
    RHS = 5 * b1 + 3 * b2 + b3
    return LHS == RHS

